<?php
session_start();require_once __DIR__.'/auth.php';ff_guard();
if (!isset($_SESSION['admin_id'])) { header('Location: login.php'); exit; }
require_once __DIR__ . '/../fastfood/database.php';
require_once __DIR__ . '/../fastfood/lang.php';

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    $id = (int)($_POST['order_id'] ?? 0);
    $action = $_POST['action'] ?? '';
    if ($id > 0) {
        if ($action === 'accept') {
            $stmt = $pdo->prepare("UPDATE orders SET status='qabul qilingan' WHERE id=? AND status='yangi'"); $stmt->execute([$id]);
        } elseif ($action === 'send_kitchen') {
            $stmt = $pdo->prepare("UPDATE orders SET status='tayyorlanmoqda' WHERE id=? AND status='qabul qilingan'"); $stmt->execute([$id]);
        } elseif ($action === 'finish') {
            $stmt = $pdo->prepare("UPDATE orders SET status='yakunlangan' WHERE id=? AND status='tayyor'"); $stmt->execute([$id]);
        } elseif ($action === 'dispatch') {
            $stmt = $pdo->prepare("UPDATE orders SET status='yetkazilmoqda' WHERE id=? AND status='tayyor' AND (table_number IS NULL OR table_number='')"); $stmt->execute([$id]);
        } elseif ($action === 'status' && isset($_POST['status'])) {
            $allowed = ['yangi','qabul qilingan','tayyorlanmoqda','tayyor','yetkazilmoqda','yakunlangan','bekor qilingan'];
            $requested = $_POST['status'];
            $os = $pdo->prepare('SELECT table_number FROM orders WHERE id=?'); $os->execute([$id]); $orderType = $os->fetchColumn();
            if ($requested === 'yetkazilmoqda' && trim((string)$orderType) !== '') { $requested = 'tayyor'; }
            if (in_array($requested, $allowed, true)) { $stmt=$pdo->prepare('UPDATE orders SET status=? WHERE id=?'); $stmt->execute([$requested,$id]); }
        }
    }
    header('Location: receive_orders.php'); exit;
}

$viewOrder = null; $viewItems=[];
if (isset($_GET['view'])) {
    $id=(int)$_GET['view'];
    $stmt=$pdo->prepare('SELECT * FROM orders WHERE id=?'); $stmt->execute([$id]); $viewOrder=$stmt->fetch();
    if ($viewOrder) { $stmt=$pdo->prepare('SELECT * FROM order_items WHERE order_id=?'); $stmt->execute([$id]); $viewItems=$stmt->fetchAll(); }
}

$q=trim($_GET['q']??''); $filter=trim($_GET['filter']??'all');
$conds=["status NOT IN ('yakunlangan','bekor qilingan')"]; $args=[];
if($filter!=='all' && in_array($filter,['yangi','qabul qilingan','tayyorlanmoqda','tayyor','yetkazilmoqda'],true)){ $conds[]='status=?'; $args[]=$filter; }
if($q!==''){ $conds[]='(CAST(id AS CHAR) LIKE ? OR customer_name LIKE ? OR phone LIKE ? OR table_number LIKE ?)'; $like='%'.$q.'%'; array_push($args,$like,$like,$like,$like); }
$sql="SELECT * FROM orders WHERE ".implode(' AND ',$conds)." ORDER BY CASE WHEN status='yangi' THEN 0 WHEN status='qabul qilingan' THEN 1 WHEN status='tayyorlanmoqda' THEN 2 WHEN status='tayyor' THEN 3 WHEN status='yetkazilmoqda' THEN 4 ELSE 5 END, created_at DESC";
$os=$pdo->prepare($sql); $os->execute($args); $orders=$os->fetchAll();
$newCount=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='yangi'")->fetchColumn();
$acceptedCount=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='qabul qilingan'")->fetchColumn();
$prepCount=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='tayyorlanmoqda'")->fetchColumn();
$deliveryCount=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='yetkazilmoqda'")->fetchColumn();
$readyCount=(int)$pdo->query("SELECT COUNT(*) FROM orders WHERE status='tayyor'")->fetchColumn();
$statuses=['yangi','qabul qilingan','tayyorlanmoqda','tayyor','yetkazilmoqda','yakunlangan','bekor qilingan'];
function statusLabel($s){ $m=['yangi'=>'Yangi','qabul qilingan'=>'Qabul qilingan','tayyorlanmoqda'=>'Tayyorlanmoqda','tayyor'=>'Tayyor','yetkazilmoqda'=>'Yetkazilmoqda','yakunlangan'=>'Yakunlangan','bekor qilingan'=>'Bekor qilingan']; return $m[$s]??$s; }
?>
