<?php include __DIR__.'/sidebar.php'; ?><main class="admin-content">
<div class="receive-head"><div><div class="eyebrow" data-i18n="BUYURTMALARNI QABUL QILISH">BUYURTMALARNI QABUL QILISH</div><h1 data-i18n="Buyurtma olish">Buyurtma olish</h1><p class="admin-muted" data-i18n="Barcha faol buyurtmalar shu bitta oynada boshqariladi.">Barcha faol buyurtmalar shu bitta oynada boshqariladi.</p></div><div class="page-actions"><span class="new-badge">🔔 <?=$newCount?> <span data-i18n="ta yangi">ta yangi</span></span><label class="btn btn-secondary" style="cursor:pointer"><input type="checkbox" id="autoRefreshOrders" checked style="margin-right:6px"> <span data-i18n="Avto yangilash">Avto yangilash</span></label><a class="btn btn-secondary" href="receive_orders.php">↻ <span data-i18n="Yangilash">Yangilash</span></a></div></div>
<form method="get" class="admin-panel" style="margin-bottom:18px;display:grid;grid-template-columns:minmax(220px,1fr) 220px auto;gap:10px;align-items:end"><label style="margin:0"><span class="admin-muted" data-i18n="Qidirish">Qidirish</span><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="ID, mijoz, telefon, stol" data-i18n-placeholder="ID, mijoz, telefon, stol"></label><label style="margin:0"><span class="admin-muted" data-i18n="Holat">Holat</span><select name="filter"><option value="all" <?=$filter==='all'?'selected':''?>>Barchasi</option><?php foreach(['yangi','qabul qilingan','tayyorlanmoqda','tayyor','yetkazilmoqda'] as $fs):?><option value="<?=$fs?>" <?=$filter===$fs?'selected':''?>><?=htmlspecialchars(statusLabel($fs))?></option><?php endforeach;?></select></label><button class="btn" data-i18n="Filtrlash">Filtrlash</button></form>
<div class="toolbar-stats"><div class="mini-stat"><span>🆕 Yangi</span><b><?=$newCount?></b></div><div class="mini-stat"><span>✓ Qabul qilingan</span><b><?=$acceptedCount?></b></div><div class="mini-stat"><span>🍳 Tayyorlanmoqda</span><b><?=$prepCount?></b></div><div class="mini-stat"><span>✅ Tayyor</span><b><?=$readyCount?></b></div><div class="mini-stat"><span>🛵 Yetkazilmoqda</span><b><?=$deliveryCount?></b></div><div class="mini-stat"><span>📦 Faol jami</span><b><?=count($orders)?></b></div></div>
<?php if($viewOrder): ?><section class="view-box"><div style="display:flex;justify-content:space-between;gap:12px;align-items:center"><h2 style="margin:0">FF-<?=str_pad($viewOrder['id'],6,'0',STR_PAD_LEFT)?></h2><span class="status-badge"><?=htmlspecialchars(statusLabel($viewOrder['status']))?></span></div><div class="receive-meta"><div><small>Mijoz</small><b><?=htmlspecialchars($viewOrder['customer_name']?:'—')?></b></div><div><small>Telefon</small><b><?=htmlspecialchars($viewOrder['phone']?:'—')?></b></div><div><small>Stol / Turi</small><b><?=htmlspecialchars($viewOrder['table_number']?'#'.$viewOrder['table_number']:'Dostavka')?></b></div><div><small>Vaqt</small><b><?=htmlspecialchars($viewOrder['created_at'])?></b></div></div><?php if($viewOrder['status']==='bekor qilingan'): $cs=$pdo->prepare('SELECT reason FROM order_cancellations WHERE order_id=? ORDER BY id DESC LIMIT 1');$cs->execute([$viewOrder['id']]);$cr=$cs->fetch();if($cr):?><div style="padding:12px;border-radius:12px;background:#fff1f2;border:1px solid #fecdd3;margin-bottom:12px"><b>Bekor qilish sababi:</b><br><?=htmlspecialchars($cr['reason'])?></div><?php endif;endif;?><table class="view-items"><tr><th>Mahsulot</th><th>Soni</th><th>Narxi</th></tr><?php foreach($viewItems as $it):?><tr><td><?=htmlspecialchars($it['product_name'])?></td><td><?=$it['quantity']?></td><td><?=number_format($it['price']*$it['quantity'],0,'',' ')?> so‘m</td></tr><?php endforeach;?></table><div style="display:flex;justify-content:space-between;margin-top:14px;font-size:18px"><b>Jami</b><b><?=number_format($viewOrder['total'],0,'',' ')?> so‘m</b></div><div class="receive-actions" style="margin-top:16px"><a class="btn" href="receipt.php?id=<?=$viewOrder['id']?>" target="_blank">🧾 Chek</a><a class="btn btn-secondary" href="receive_orders.php">Orqaga</a></div></section><?php endif; ?>
<?php if(!$orders): ?><div class="receive-empty"><div style="font-size:52px">🛎️</div><h2 data-i18n="Faol buyurtma yo‘q">Faol buyurtma yo‘q</h2><p class="admin-muted">Yangi buyurtma kelganda shu yerda ko‘rinadi.</p></div><?php else: ?><div class="receive-grid">
<?php foreach($orders as $o): $itemsStmt=$pdo->prepare('SELECT product_name,quantity,price FROM order_items WHERE order_id=?');$itemsStmt->execute([$o['id']]);$items=$itemsStmt->fetchAll(); ?><article class="receive-card <?=$o['status']==='yangi'?'new':''?>"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px"><div class="receive-id">FF-<?=str_pad($o['id'],6,'0',STR_PAD_LEFT)?></div><span class="status-badge"><?=htmlspecialchars(statusLabel($o['status']))?></span></div><div class="receive-meta"><div><small>Mijoz</small><b><?=htmlspecialchars($o['customer_name']?:'—')?></b></div><div><small>Telefon</small><b><?=htmlspecialchars($o['phone']?:'—')?></b></div><div><small>Stol / Turi</small><b><?=htmlspecialchars($o['table_number']?'#'.$o['table_number']:'Dostavka')?></b></div><div><small>Vaqt</small><b><?=htmlspecialchars($o['created_at'])?></b></div></div><div style="border-top:1px dashed var(--line);padding-top:10px;margin-bottom:12px"><?php foreach($items as $it):?><div style="display:flex;justify-content:space-between;gap:10px;padding:5px 0"><span><?=htmlspecialchars($it['product_name'])?> × <?=$it['quantity']?></span><b><?=number_format($it['price']*$it['quantity'],0,'',' ')?> so‘m</b></div><?php endforeach;?></div><div style="display:flex;justify-content:space-between;font-size:18px;margin-bottom:12px"><b>Jami</b><b><?=number_format($o['total'],0,'',' ')?> so‘m</b></div><div class="receive-actions"><?php if($o['status']==='yangi'):?><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="accept"><button class="btn" type="submit">✓ Buyurtmani olish</button></form><?php elseif($o['status']==='qabul qilingan'):?><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="send_kitchen"><button class="btn" type="submit">🍳 Oshxonaga yuborish</button></form><?php elseif($o['status']==='tayyor'):?><?php if(empty($o['table_number'])):?><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="dispatch"><button class="btn" type="submit">🛵 Yetkazishga berish</button></form><?php else:?><form method="post"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="finish"><button class="btn" type="submit">✓ Buyurtmani yakunlash</button></form><?php endif;?><?php endif;?><a class="btn btn-secondary" href="receive_orders.php?view=<?=$o['id']?>">Ko‘rish</a></div><form method="post" style="margin-top:8px"><input type="hidden" name="order_id" value="<?=$o['id']?>"><input type="hidden" name="action" value="status"><select class="status-select" name="status" onchange="this.form.submit()"><?php foreach($statuses as $s):?><option value="<?=$s?>" <?=$o['status']===$s?'selected':''?>><?=htmlspecialchars(statusLabel($s))?></option><?php endforeach;?></select></form></article><?php endforeach;?></div><?php endif; ?>
</main><script src="../js/lang-switch.js"></script><script>const ar=document.getElementById('autoRefreshOrders'); if(ar){ar.checked=localStorage.getItem('ff-auto-orders')!=='0'; ar.onchange=()=>localStorage.setItem('ff-auto-orders',ar.checked?'1':'0');} setInterval(()=>{if(!ar||ar.checked) location.reload()},15000);</script></body></html>
